def _check_duplicate_entity_in_model(params):
    models = params.models

    dict_entity = {"Surface": {}, "Volume": {}}

    if models:
        for model in models:
            if hasattr(model, "entities"):
                for entity in model.entities.stored_entities:
                    dict_entity = _register_single_entity(entity, model.type, dict_entity)

    error_msg = ""
    for entity_type in dict_entity.keys():
        for entity_name, model_set in dict_entity[entity_type].items():
            if len(model_set) > 1:
                model_string = ",".join(f"`{x}`" for x in model_set)
                error_msg += (
                    f"{entity_type} entity `{entity_name}` appears "
                    f"multiple times in {model_string} model.\n"
                )
    if error_msg:
        raise ValueError(error_msg)

    return params


def _register_single_entity(entity, model_type, dict_entity):
    if isinstance(entity, _SurfaceEntityBase):
        dict_entity["Surface"].setdefault(entity.name, set()).add(model_type)

    if isinstance(entity, _VolumeEntityBase):
        dict_entity["Volume"].setdefault(entity.name, set()).add(model_type)

    return dict_entity
